  ('gba-1', '06410'),
  -- 2do cordón: Quilmes, Berazategui, Florencio Varela, Almirante Brown, Esteban Echeverría, Ezeiza,
  -- Merlo, Moreno, José C. Paz, Malvinas Argentinas, San Miguel, San Fernando, Tigre.
